-- Карточка заявки для мастера, счётчики «Назначено вам / Новые» на главной,
-- названия-обрывки в прайсе (63 позиции, список согласован с заказчиком 13.10.2026).
-- Откат: supabase/rollback/20261014000001_request_card_down.sql

-- ---------- Прайс: «из ламината, …» → «Разборка покрытий полов: из ламината, …» ----------
-- Полный текст обрезанных названий взят из старой части исходного прайса (data/price_2026_max.csv).
create table public.price_item_renames (
  price_item_id bigint primary key references public.price_items (id),
  old_name      text not null,
  new_name      text not null,
  renamed_at    timestamptz not null default now()
);
alter table public.price_item_renames enable row level security;
revoke all on public.price_item_renames from anon, authenticated;

-- Позиция ищется по номеру, а если номер другой (тестовая база) — по полному и короткому названию.
